//! Scratch harness mirroring the unit-test compress options.
use std::path::Path;

use oxc_allocator::Allocator;
use oxc_codegen::{Codegen, CodegenOptions};
use oxc_minifier::{CompressOptions, CompressOptionsKeepNames, CompressOptionsUnused, Compressor};
use oxc_parser::{ParseOptions, Parser};
use oxc_span::SourceType;

fn default_options() -> CompressOptions {
    CompressOptions {
        drop_debugger: false,
        unused: CompressOptionsUnused::Keep,
        ..CompressOptions::smallest()
    }
}

fn run(source_text: &str, keep_names: bool) -> String {
    let allocator = Allocator::default();
    let source_type = SourceType::mjs();
    let ret = Parser::new(&allocator, source_text, source_type)
        .with_options(ParseOptions { allow_return_outside_function: true, ..Default::default() })
        .parse();
    assert!(!ret.panicked, "{source_text}");
    let mut program = ret.program;
    let mut options = default_options();
    if keep_names {
        options.keep_names = CompressOptionsKeepNames::all_true();
    }
    Compressor::new(&allocator).build(&mut program, options);
    Codegen::new()
        .with_options(CodegenOptions { single_quote: true, ..Default::default() })
        .build(&program)
        .code
}

fn main() {
    let name = std::env::args().nth(1).unwrap_or_else(|| "test.js".to_string());
    let keep_names = std::env::args().any(|a| a == "--keep-names");
    let source_text = std::fs::read_to_string(Path::new(&name)).unwrap();
    print!("{}", run(&source_text, keep_names));
}
