//! Scratch harness mirroring the may_have_side_effects test Ctx.
use rustc_hash::FxHashSet;

use oxc_allocator::Allocator;
use oxc_ast::ast::{Expression, IdentifierReference, Statement};
use oxc_ecmascript::{
    GlobalContext,
    side_effects::{MayHaveSideEffects, MayHaveSideEffectsContext, PropertyReadSideEffects},
};
use oxc_parser::Parser;
use oxc_span::SourceType;

struct Ctx {
    globals: FxHashSet<String>,
}

impl<'a> GlobalContext<'a> for Ctx {
    fn is_global_reference(&self, ident: &IdentifierReference<'a>) -> bool {
        self.globals.contains(ident.name.as_str())
    }
}

impl MayHaveSideEffectsContext<'_> for Ctx {
    fn annotations(&self) -> bool {
        true
    }
    fn manual_pure_functions(&self, _callee: &Expression) -> bool {
        false
    }
    fn property_read_side_effects(&self) -> PropertyReadSideEffects {
        PropertyReadSideEffects::All
    }
    fn property_write_side_effects(&self) -> bool {
        true
    }
    fn unknown_global_side_effects(&self) -> bool {
        true
    }
}

fn check(src: &str, globals: &[&str], expected: bool) {
    let allocator = Allocator::default();
    let ret = Parser::new(&allocator, src, SourceType::mjs()).parse();
    let Some(Statement::ExpressionStatement(stmt)) = ret.program.body.first() else {
        println!("PARSE-FAIL: {src}");
        return;
    };
    let ctx = Ctx { globals: globals.iter().map(|s| (*s).to_string()).collect() };
    let got = stmt.expression.may_have_side_effects(&ctx);
    let mark = if got == expected { "ok  " } else { "FAIL" };
    println!("{mark} expect={expected:5} got={got:5}  [{}]  {src}", globals.join(","));
}

fn main() {
    // req1: well-known builtins side-effect-free even when in explicit list
    for g in ["Math", "Array", "Object", "JSON", "Reflect", "Symbol", "Promise", "Map", "Set",
        "WeakMap", "WeakSet", "parseInt", "parseFloat", "isNaN", "isFinite", "encodeURI",
        "decodeURI", "globalThis"] {
        check(g, &[g], false);
    }
    // req2: known-safe env globals free; unknown explicit globals have side effects
    check("console", &["console"], false);
    check("document", &["document"], false);
    check("window", &["window"], false);
    check("fetch", &["fetch"], false);
    check("myGlobal", &["myGlobal"], true);
    check("a", &["a"], true);

    // req3: known property reads
    check("Math.PI", &["Math"], false);
    check("Math.E", &["Math"], false);
    check("Math.floor", &["Math"], false);
    check("Math.random", &["Math"], false);
    check("Math.unknownProp", &["Math"], true);
    check("Object.keys", &["Object"], false);
    check("Object.create", &["Object"], false);
    check("Object.assign", &["Object"], false);
    check("Object.prototype", &["Object"], false);
    check("Object.unknown", &["Object"], true);
    check("Reflect.apply", &["Reflect"], false);
    check("Reflect.get", &["Reflect"], false);
    check("Reflect.unknown", &["Reflect"], true);
    check("Symbol.iterator", &["Symbol"], false);
    check("Symbol.asyncIterator", &["Symbol"], false);
    check("Symbol.unknown", &["Symbol"], true);
    check("JSON.parse", &["JSON"], false);
    check("JSON.stringify", &["JSON"], false);
    check("JSON.unknown", &["JSON"], true);

    // req4: console methods
    check("console.log", &["console"], false);
    check("console.error", &["console"], false);
    check("console.warn", &["console"], false);
    check("console.info", &["console"], true);
    check("console.log", &[], false); // console not in list -> treated as local -> no side effect

    // req5: Object.prototype three-level chains
    check("Object.prototype.hasOwnProperty", &["Object"], false);
    check("Object.prototype.isPrototypeOf", &["Object"], false);
    check("Object.prototype.toString", &["Object"], false);
    check("Object.prototype.valueOf", &["Object"], false);
    check("Object.prototype.propertyIsEnumerable", &["Object"], false);
    check("Object.prototype.unknownProp", &["Object"], true);
    check("Math.PI.toString", &["Math"], true);
    check("Array.prototype.push", &["Array"], true);

    // req6: Symbol() pure
    check("Symbol()", &["Symbol"], false);
}
